package io.github.diodeme.ji.host;

import io.github.diodeme.ji.agent.PermissionDecider;
import java.time.Clock;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionStage;
import java.util.concurrent.ConcurrentHashMap;

/** Durable-boundary projection for pending permission decisions with first-answer CAS semantics. */
public final class PermissionBroker implements PermissionDecider {
    private final Map<String, Pending> pending = new ConcurrentHashMap<>();
    private final Clock clock;

    public PermissionBroker(Clock clock) {
        this.clock = clock;
    }

    @Override
    public CompletionStage<Decision> decide(Request request) {
        if (!clock.instant().isBefore(request.expiresAt())) return CompletableFuture.completedFuture(Decision.DENY);
        var result = new CompletableFuture<Decision>();
        Pending prior = pending.putIfAbsent(request.permissionId(), new Pending(request, result));
        if (prior != null) throw new IllegalStateException("permission id already exists");
        result.whenComplete((ignored, failure) -> pending.remove(request.permissionId()));
        return result;
    }

    public Optional<Request> pending(String permissionId) {
        Pending value = pending.get(permissionId);
        return value == null ? Optional.empty() : Optional.of(value.request);
    }

    public boolean answer(String permissionId, long expectedRevision, Decision decision) {
        Pending value = pending.get(permissionId);
        if (value == null || value.request.revision() != expectedRevision) return false;
        return value.result.complete(decision);
    }

    private record Pending(Request request, CompletableFuture<Decision> result) {}
}
